def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    y = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                y.append(z)
        except (TypeError, ValueError):
            pass
    if horizon <= 0:
        return []
    if not y:
        return [0.0] * horizon
    p = 7 if len(y) >= 21 else 1
    if len(y) < 3 * p:
        return [float(statistics.median(y))] * horizon
    candidates = [0, 1, 3, 5, 9, 13]
    def predict_at(origin, target, k):
        if k == 0:
            return float(statistics.median(y[max(0, origin - 4 * p):origin]))
        phase = target % p
        vals = [y[i] for i in range(phase, origin, p)]
        return float(statistics.median(vals[-k:])) if vals else y[origin - 1]
    first = max(2 * p, len(y) - 10 * p)
    origins = list(range(first, len(y) - p + 1, p))
    errors = {}
    for k in candidates:
        losses = []
        for origin in origins:
            for h in range(p):
                actual = y[origin + h]
                pred = predict_at(origin, origin + h, k)
                den = abs(actual) + abs(pred)
                losses.append(0.0 if den < 1e-12 else 200.0 * abs(actual - pred) / den)
        errors[k] = sum(losses) / len(losses) if losses else float('inf')
    ranked = sorted(candidates, key=lambda k: errors[k])
    chosen = ranked[:2] if len(ranked) > 1 and errors[ranked[1]] <= errors[ranked[0]] + 1.5 else ranked[:1]
    result = []
    n = len(y)
    for h in range(1, horizon + 1):
        target = n + h - 1
        preds = [predict_at(n, target, k) for k in chosen]
        result.append(float(sum(preds) / len(preds)))
    return result

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    y = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                y.append(z)
        except (TypeError, ValueError):
            pass
    if horizon <= 0:
        return []
    if not y:
        return [0.0] * horizon
    p = 7 if len(y) >= 21 else 1
    if len(y) < 4 * p:
        return [float(statistics.median(y))] * horizon
    alphas = [0.0, 0.25, 0.5, 0.75, 1.0]
    def fit(origin):
        start = max(0, origin - 16 * p)
        phase_medians = []
        for phase in range(p):
            vals = [y[i] for i in range(start, origin) if i % p == phase]
            phase_medians.append(float(statistics.median(vals)) if vals else y[origin - 1])
        profile_center = float(statistics.median(phase_medians))
        recent_level = float(statistics.median(y[max(0, origin - 2 * p):origin]))
        return phase_medians, profile_center, recent_level
    first = max(3 * p, len(y) - 10 * p)
    origins = list(range(first, len(y) - p + 1, p))
    scores = {}
    for alpha in alphas:
        losses = []
        for origin in origins:
            profile, center, level = fit(origin)
            for h in range(p):
                actual = y[origin + h]
                pred = level + alpha * (profile[(origin + h) % p] - center)
                den = abs(actual) + abs(pred)
                losses.append(0.0 if den < 1e-12 else 200.0 * abs(actual - pred) / den)
        scores[alpha] = sum(losses) / len(losses) if losses else float('inf')
    alpha = min(alphas, key=lambda a: scores[a])
    profile, center, level = fit(len(y))
    return [float(level + alpha * (profile[(len(y) + h - 1) % p] - center)) for h in range(1, horizon + 1)]

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    y = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                y.append(z)
        except (TypeError, ValueError):
            pass
    if horizon <= 0:
        return []
    if not y:
        return [0.0] * horizon
    p = 7 if len(y) >= 21 else 1
    if len(y) < 3 * p:
        return [float(statistics.median(y))] * horizon
    profiles = []
    for phase in range(p):
        vals = [y[i] for i in range(phase, len(y), p)][-16:]
        med = float(statistics.median(vals))
        deviations = [abs(v - med) for v in vals]
        mad = float(statistics.median(deviations))
        scale = max(1.4826 * mad, 0.05 * max(abs(med), 1.0))
        clean = [v for v in vals if abs(v - med) <= 2.5 * scale]
        clean_center = float(statistics.median(clean[-7:])) if clean else med
        latest = vals[-1]
        if abs(latest - med) <= 2.5 * scale:
            estimate = 0.6 * latest + 0.4 * clean_center
        else:
            estimate = clean_center
        profiles.append(float(estimate))
    result = []
    n = len(y)
    for h in range(1, horizon + 1):
        result.append(profiles[(n + h - 1) % p])
    return result
